<?php
namespace App\Domain\Products;use App\Domain\PublicChrome\{PublicAssetPath,PublicLink};use App\Models\Product;use Illuminate\Support\Facades\Cache;use Throwable;final class ProductViewData {public function published(string $slug):?array{try{$p=Product::publiclyVisible()->where('slug',$slug)->first();if(!$p)return null;return Cache::remember("public.products.v1.$p->id.$slug.".ProductCache::version($p->id),now()->addMinutes(15),fn()=>$this->transform($this->load($p),false));}catch(Throwable){return $this->direct($slug);}}public function preview(Product $p):array{return $this->transform($this->load($p),true);}private function load(Product $p):Product{return $p->load(['category','editions'=>fn($q)=>$q->orderBy('display_order')->limit(8),'featureGroups'=>fn($q)=>$q->with(['features'=>fn($f)=>$f->orderBy('display_order')->limit(20)])->orderBy('display_order')->limit(10),'benefits'=>fn($q)=>$q->orderBy('display_order')->limit(12),'specifications'=>fn($q)=>$q->orderBy('display_order')->limit(40),'galleryItems'=>fn($q)=>$q->orderBy('display_order')->limit(12),'useCases'=>fn($q)=>$q->orderBy('display_order')->limit(12),'integrations'=>fn($q)=>$q->orderBy('display_order')->limit(20),'relatedProducts'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedSolutions'=>fn($q)=>$q->publiclyVisible()->limit(6),'relatedPages'=>fn($q)=>$q->publiclyVisible()->limit(6)]);}private function transform(Product $p,bool $preview):array{$active=fn($c)=>$c->filter(fn($x)=>$preview||$x->is_active);$basic=fn($c)=>$active($c)->map(fn($x)=>['title'=>$x->title??$x->name,'description'=>$x->description??$x->short_description??null,'icon'=>in_array($x->icon??null,ProductRegistry::ICONS,true)?$x->icon:null,'sector'=>$x->sector??null,'slug'=>$x->slug??null,'type'=>$x->edition_type??null,'badge'=>$x->badge_text??null])->values()->all();return ['title'=>$p->title,'slug'=>$p->slug,'eyebrow'=>$p->eyebrow,'short_description'=>$p->short_description,'overview'=>$p->overview,'problem_statement'=>$p->problem_statement,'value_proposition'=>$p->value_proposition,'image'=>PublicAssetPath::isSafe($p->featured_image_path)?$p->featured_image_path:null,'image_alt'=>$p->featured_image_alt,'category'=>$p->category&&$p->category->is_active?['name'=>$p->category->name,'slug'=>$p->category->slug]:null,'editions'=>$basic($p->editions),'feature_groups'=>$active($p->featureGroups)->map(fn($g)=>['title'=>$g->title,'description'=>$g->description,'features'=>$basic($g->features)])->values()->all(),'benefits'=>$basic($p->benefits),'specifications'=>$active($p->specifications)->map(fn($x)=>['label'=>$x->label,'value'=>$x->value,'group'=>$x->group_name])->values()->all(),'gallery'=>$active($p->galleryItems)->filter(fn($x)=>PublicAssetPath::isSafe($x->image_path))->map(fn($x)=>['image'=>$x->image_path,'alt'=>$x->image_alt,'caption'=>$x->caption])->values()->all(),'use_cases'=>$basic($p->useCases),'integrations'=>$active($p->integrations)->map(fn($x)=>['name'=>$x->name,'description'=>$x->description,'logo'=>PublicAssetPath::isSafe($x->logo_path)?$x->logo_path:null,'logo_alt'=>$x->logo_alt,'url'=>PublicLink::isSafeUrl($x->website_url)?$x->website_url:null])->values()->all(),'related_products'=>$p->relatedProducts->map(fn($x)=>['title'=>$x->title,'description'=>$x->short_description,'url'=>route('products.show',$x->slug)])->all(),'related_solutions'=>$p->relatedSolutions->map(fn($x)=>['title'=>$x->title,'description'=>$x->short_description,'url'=>route('solutions.show',$x->slug)])->all(),'related_pages'=>$p->relatedPages->map(fn($x)=>['title'=>$x->title,'url'=>route('pages.show',$x->slug)])->all(),'ctas'=>array_values(array_filter([$this->link($p->primary_cta_label,$p->primary_cta_url),$this->link($p->secondary_cta_label,$p->secondary_cta_url),$this->link($p->demo_cta_label,$p->demo_cta_url)])),'documentation_url'=>PublicLink::isSafeUrl($p->documentation_url)?$p->documentation_url:null,'meta_title'=>$p->meta_title?:$p->title,'meta_description'=>$p->meta_description?:$p->short_description,'og_title'=>$p->og_title?:($p->meta_title?:$p->title),'og_description'=>$p->og_description?:($p->meta_description?:$p->short_description),'og_image'=>PublicAssetPath::isSafe($p->og_image_path)?$p->og_image_path:null,'canonical_url'=>$p->canonical_url,'robots'=>$preview?'noindex, nofollow':(($p->robots_index?'index':'noindex').', '.($p->robots_follow?'follow':'nofollow'))];}private function direct(string $slug):?array{try{$p=Product::publiclyVisible()->where('slug',$slug)->first();return $p?$this->transform($this->load($p),false):null;}catch(Throwable){return null;}}private function link(?string $l,?string $u):?array{return $l&&$u&&PublicLink::isSafeUrl($u)?['label'=>$l,'url'=>$u]:null;}}